// Torah Save Worker v2.0 - Strict validation with kind-based routing
const input = $input.first().json;
const body = input.body || input;

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const isValidUUID = (str) => str && UUID_REGEX.test(str);

// Helper for error response
const errorResponse = (code, message) => [{
  json: {
    success: false,
    error: { code: code, message: message }
  }
}];

// ============================================
// VALIDATION v2.0
// ============================================

if (!body.translated_text && !body.translation) {
  return errorResponse('MISSING_TRANSLATION', 'translated_text or translation is required');
}

// kind is REQUIRED in v2.0
const kind = body.kind;
if (!kind) {
  return errorResponse('MISSING_KIND', "Field 'kind' is required. Must be 'segment' or 'commentary'.");
}
if (!['segment', 'commentary'].includes(kind)) {
  return errorResponse('INVALID_KIND', `Invalid kind '${kind}'. Must be 'segment' or 'commentary'.`);
}

// Validate ID based on kind
if (kind === 'segment') {
  if (!isValidUUID(body.segment_id)) {
    return errorResponse('MISSING_SEGMENT_ID', "Field 'segment_id' (UUID) is required when kind='segment'.");
  }
}

if (kind === 'commentary') {
  if (!isValidUUID(body.commentary_detail_id)) {
    return errorResponse('MISSING_COMMENTARY_DETAIL_ID', "Field 'commentary_detail_id' (UUID) is required when kind='commentary'.");
  }
}

// ============================================
// OUTPUT
// ============================================

return [{
  json: {
    valid: true,
    kind: kind,
    jobId: body.job_id,
    translation: body.translated_text || body.translation,
    segmentId: kind === 'segment' ? body.segment_id : null,
    commentaryDetailId: kind === 'commentary' ? body.commentary_detail_id : null,
    targetLanguage: body.target_language || 'fr',
    provider: body.provider || 'anthropic',
    model: body.model || 'claude-sonnet-4-20250514',
    qualityScore: body.quality_score || null,
    confidenceScore: body.confidence_score || null,
    requestId: body.request_id || null,
    llmUsage: body.llm_usage || null,
    status: body.status || 'approved',
    notes: body.notes || null,
    issues: body.issues || [],
    extraData: body.extra_data || {}
  }
}];

// Format success response
const input = $input.first().json;
const parseData = $('Parse Input').first().json;

if (input.error) {
  return [{
    json: {
      success: false,
      kind: parseData.kind,
      error: {
        code: 'SAVE_ERROR',
        message: input.error.message || input.detail?.message || 'Failed to save translation'
      }
    }
  }];
}

return [{
  json: {
    success: input.success !== false,
    kind: parseData.kind,
    translation_id: input.translation_id || input.id,
    segment_id: parseData.segmentId,
    commentary_detail_id: parseData.commentaryDetailId,
    target_language: parseData.targetLanguage,
    version: input.version || 1,
    status: input.status || 'approved',
    created_at: input.created_at,
    message: input.message || 'Translation saved'
  }
}];
